// Design tokens: the only source of colour, type, space, shape and motion values.
// Web reads them as CSS custom properties (generated by scripts/tokens.ts);
// the Expo app imports `theme` below. The look is docs/design/v4 (B2): Joi-calm monochrome,
// Inter, one red "now", light and dark.

import { oklchStringToHex } from "./color.ts";

export const SCHEMES = ["light", "dark"] as const;
export type Scheme = (typeof SCHEMES)[number];

type Solid =
  | "bg"
  | "raised"
  | "overlay"
  | "sunken"
  | "ink"
  | "ink2"
  | "ink3"
  | "onInk"
  | "now"
  | "head"
  | "headInk"
  | "headDim"
  | "parse"
  | "done";
type Alpha = "hover" | "select" | "line" | "lineStrong" | "scrim";
type ColorName = Solid | Alpha;

// Every text colour holds 4.5:1 on bg, raised and sunken in its scheme; ink3 is the faintest
// text allowed (Joi's lighter grey failed that, so ink3 is a step darker than Joi's).
const solid: Record<Scheme, Record<Solid, string>> = {
  light: {
    bg: "oklch(100% 0 0)",
    raised: "oklch(100% 0 0)",
    overlay: "oklch(100% 0 0)",
    sunken: "oklch(96.5% 0.002 286)",
    ink: "oklch(17% 0.004 286)",
    ink2: "oklch(36% 0.008 286)",
    ink3: "oklch(51% 0.008 286)",
    onInk: "oklch(100% 0 0)",
    now: "oklch(55% 0.19 29)",
    // The Today header is black in both schemes, like Joi's top card.
    head: "oklch(13% 0.003 286)",
    headInk: "oklch(100% 0 0)",
    headDim: "oklch(66% 0.008 286)",
    parse: "oklch(53% 0.18 255)",
    done: "oklch(52% 0.13 150)",
  },
  dark: {
    bg: "oklch(13% 0.004 286)",
    raised: "oklch(19.5% 0.005 286)",
    overlay: "oklch(23% 0.005 286)",
    sunken: "oklch(21.5% 0.005 286)",
    ink: "oklch(96.5% 0.003 286)",
    ink2: "oklch(86% 0.006 286)",
    ink3: "oklch(72% 0.008 286)",
    onInk: "oklch(15% 0.004 286)",
    now: "oklch(68% 0.19 27)",
    head: "oklch(0% 0 0)",
    headInk: "oklch(100% 0 0)",
    headDim: "oklch(66% 0.008 286)",
    parse: "oklch(72% 0.14 250)",
    done: "oklch(72% 0.15 150)",
  },
};

/** Translucent layers: black over light, white over dark. */
const alpha: Record<Scheme, Record<Alpha, string>> = {
  light: {
    hover: "oklch(0% 0 0 / 0.04)",
    select: "oklch(0% 0 0 / 0.07)",
    line: "oklch(0% 0 0 / 0.09)",
    lineStrong: "oklch(0% 0 0 / 0.16)",
    scrim: "oklch(0% 0 0 / 0.32)",
  },
  dark: {
    hover: "oklch(100% 0 0 / 0.05)",
    select: "oklch(100% 0 0 / 0.09)",
    line: "oklch(100% 0 0 / 0.08)",
    lineStrong: "oklch(100% 0 0 / 0.15)",
    scrim: "oklch(0% 0 0 / 0.55)",
  },
};

export const SPACE_COLORS = ["blue", "green", "orange", "purple", "red", "yellow", "teal", "pink"] as const;
export type SpaceColor = (typeof SPACE_COLORS)[number];

const spaceHue: Record<SpaceColor, number> = {
  blue: 245,
  green: 150,
  orange: 62,
  purple: 305,
  red: 18,
  yellow: 92,
  teal: 195,
  pink: 345,
};
// Dots carry meaning only next to a name, so they need 3:1, not 4.5:1, against their ground.
const spaceOklch = (scheme: Scheme, c: SpaceColor) =>
  scheme === "light"
    ? `oklch(${c === "yellow" ? 70 : 58}% 0.14 ${spaceHue[c]})`
    : `oklch(${c === "yellow" ? 80 : 74}% 0.085 ${spaceHue[c]})`;
const surfaceOklch = (scheme: Scheme, c: SpaceColor) =>
  scheme === "light" ? `oklch(95.5% 0.03 ${spaceHue[c]})` : `oklch(25% 0.03 ${spaceHue[c]})`;

const hexAll = (values: Record<string, string>) =>
  Object.fromEntries(Object.entries(values).map(([k, v]) => [k, oklchStringToHex(v)]));

export interface SpaceTones {
  css: string;
  cssSurface: string;
  dot: string;
  surface: string;
}

export interface SchemeTokens {
  /** CSS values (oklch) by token name. */
  css: Record<ColorName, string>;
  /** Hex values for React Native and SVG. Alpha layers become #rrggbbaa. */
  color: Record<ColorName, string>;
  space: Record<SpaceColor, SpaceTones>;
}

export const schemes = Object.fromEntries(
  SCHEMES.map((scheme) => {
    const cssValues = { ...solid[scheme], ...alpha[scheme] };
    return [
      scheme,
      {
        css: cssValues,
        color: hexAll(cssValues) as Record<ColorName, string>,
        space: Object.fromEntries(
          SPACE_COLORS.map((c) => [
            c,
            {
              css: spaceOklch(scheme, c),
              cssSurface: surfaceOklch(scheme, c),
              dot: oklchStringToHex(spaceOklch(scheme, c)),
              surface: oklchStringToHex(surfaceOklch(scheme, c)),
            },
          ]),
        ) as Record<SpaceColor, SpaceTones>,
      },
    ];
  }),
) as Record<Scheme, SchemeTokens>;

/** Light values, for callers that draw one fixed picture (the site's icons, the CLI). */
export const css = schemes.light.css;
export const color = schemes.light.color;
export const spaceColor = schemes.light.space;

export const font = {
  family: "Inter",
  weights: { regular: "400", medium: "500", semibold: "600" },
} as const;

export interface TypeRole {
  size: number;
  line: number;
  weight: "400" | "500" | "600";
  tracking: number;
}

/** Six sizes: 12, 14, 16, 20, 28, 40. Phones use `phoneType`, where body grows to 16. */
export const type: Record<
  "caption" | "meta" | "body" | "label" | "subhead" | "title" | "headline" | "display",
  TypeRole
> = {
  caption: { size: 12, line: 16, weight: "500", tracking: 0 },
  meta: { size: 12, line: 16, weight: "400", tracking: 0 },
  body: { size: 14, line: 20, weight: "400", tracking: 0 },
  label: { size: 14, line: 20, weight: "500", tracking: 0 },
  subhead: { size: 16, line: 24, weight: "600", tracking: -0.01 },
  title: { size: 20, line: 28, weight: "600", tracking: -0.01 },
  headline: { size: 28, line: 32, weight: "600", tracking: -0.02 },
  display: { size: 40, line: 44, weight: "600", tracking: -0.03 },
};

export const phoneType: typeof type = {
  ...type,
  meta: { size: 14, line: 20, weight: "400", tracking: 0 },
  body: { size: 16, line: 24, weight: "400", tracking: 0 },
  label: { size: 16, line: 24, weight: "500", tracking: 0 },
};

export const TYPE_SCALE = [12, 14, 16, 20, 28, 40] as const;

/** 4px steps that grow as the gaps grow. */
export const space = { s1: 4, s2: 8, s3: 12, s4: 16, s6: 24, s8: 32, s12: 48, s16: 64 } as const;
export const SPACE_SCALE = Object.values(space);

export const radius = { sm: 6, ctl: 8, card: 12, sheet: 24 } as const;

export const size = {
  ctl: 32,
  row: 36,
  touch: 44,
  phoneRow: 48,
  column: 680,
  sidebar: 248,
  panel: 440,
  /** Upcoming's tray of tasks still to plan, beside the week. */
  tray: 224,
  /**
   * Today's schedule beside the list. With the 48 gap and the page's 32 padding it is wider
   * than the task panel (440), so an open panel covers the schedule and never the list.
   */
  schedule: 400,
} as const;

/** From this window width Today puts the schedule beside the list: sidebar, a 560 list, the schedule. */
export const SPLIT_MIN_WIDTH = 1320;

/** Light schemes separate surfaces with a soft shadow; dark ones with a faint light edge. */
export const shadows: Record<Scheme, { raised: string; overlay: string }> = {
  light: {
    raised: "0 0 0 1px oklch(0% 0 0 / 0.05), 0 1px 2px oklch(0% 0 0 / 0.06)",
    overlay:
      "0 0 0 1px oklch(0% 0 0 / 0.06), 0 2px 6px oklch(0% 0 0 / 0.06), 0 16px 40px oklch(0% 0 0 / 0.12)",
  },
  dark: {
    raised:
      "inset 0 0 0 1px oklch(100% 0 0 / 0.05), inset 0 1px 0 oklch(100% 0 0 / 0.04), 0 1px 2px oklch(0% 0 0 / 0.3)",
    overlay:
      "inset 0 0 0 1px oklch(100% 0 0 / 0.08), inset 0 1px 0 oklch(100% 0 0 / 0.05), 0 2px 6px oklch(0% 0 0 / 0.3), 0 16px 40px oklch(0% 0 0 / 0.45)",
  },
};
export const shadow = shadows.light;

export const motion = {
  press: 160,
  enter: 220,
  exit: 150,
  pressScale: 0.97,
  easeOut: [0.23, 1, 0.32, 1] as const,
  easeInOut: [0.77, 0, 0.175, 1] as const,
} as const;

